/**
 * Vertical metrics (em) of the fonts that ship with Windows and Office, in the
 * form PowerPoint lays a single line out on: `[ascent, descent, lineGap]`.
 *
 * Measured on PowerPoint 16 exports of an `H` at 72pt in every font of the
 * Windows font folder (235 families): a font without the `USE_TYPO_METRICS`
 * bit (`OS/2.fsSelection` bit 7) is laid out on its Windows ascent and
 * descent (`winAscent`, `winDescent`; no line gap), one with the bit on its
 * typographic ones (`sTypoAscender`, `sTypoDescender`) with `sTypoLineGap`
 * added above the ascent; either way the box is scaled to a 1.2 em pitch.
 * The values were read from the font files with fontTools. A renderer needs
 * them for a font the browser does not have (Office cloud fonts such as
 * OCR A Extended or Eras ITC, a styled face name such as Nirmala Text
 * Semilight), where the browser would measure a stand-in.
 *
 * Generated; keys are lower-case font names.
 *
 * @module text/font-metrics/office-font-metrics.generated
 */

/** `[ascent, descent, lineGap]` in em. */
export type OfficeFontMetrics = readonly [number, number, number];

